import (
	context "context"
	fern "github.com/go-request-body-pagination/fern"
	fernclient "github.com/go-request-body-pagination/fern/client"
)

client := fernclient.NewClient()
response, err := client.Users.ListWithBodyCursorPagination(
	context.TODO(),
	&fern.ListUsersBodyCursorPaginationRequest{
		Cursor: fern.String(
			"cursor",
		),
		Filter: fern.String(
			"filter",
		),
	},
)

